# ТІЛЬКИ ЧИТАННЯ: які логіни лежать у двох файлах доступів
for f in ('/root/unitex-finrep/secure/odata.env','/root/unitex-finrep/secure/odata_write.env'):
    env={}
    try:
        for l in open(f,encoding='utf-8'):
            l=l.strip()
            if l and not l.startswith('#') and '=' in l:
                k,v=l.split('=',1); env[k.strip()]=v.strip()
        print(f, "-> ODATA_USER =", repr(env.get('ODATA_USER')), "| довжина пароля:", len(env.get('ODATA_PASS','')))
    except Exception as e:
        print(f, "->", e)
